use tokio::sync::oneshot;

enum Msg { Add(i64), Get(oneshot::Sender<i64>) }

let (tx, mut rx) = tokio::sync::mpsc::channel::<Msg>(64);   // bounded mailbox
tokio::spawn(async move {
    let mut count = 0i64;                                   // owned by this task only
    while let Some(msg) = rx.recv().await {
        match msg {
            Msg::Add(n) => count += n,
            Msg::Get(reply) => { let _ = reply.send(count); }
        }
    }
});
tx.send(Msg::Add(1)).await?;                                 // tx is the address
